after:
```swift
protocol ItemSource {
    associatedtype Item
    var item: Item { get }
}
struct Box<Value>: ItemSource {
    let item: Value
}
struct CountSource: ItemSource {
    let item: Int
}
func pair<A: ItemSource, B: ItemSource>(_ a: A, _ b: B) -> [A.Item]
where A.Item == B.Item {
    return [a.item, b.item]
}
print(pair(Box(item: 6), CountSource(item: 9)))
```
This prints [6, 9]. The box supplies 6 and CountSource supplies 9. Both items are Int values, so they can go in the returned array together.
